widget.solution:
def touch_prob(n, m, p):
    """Exact chance that a walk from 0, stepping +1 with
    probability p and -1 otherwise, reaches level m
    within n steps."""
    if m <= 0:
        return 1.0
    dist = {0: 1.0}   # position -> probability, not yet hit
    hit = 0.0
    for _ in range(n):
        new = {}
        for s, pr in dist.items():
            for step, q in ((1, p), (-1, 1 - p)):
                t = s + step
                if t >= m:
                    hit += pr * q
                else:
                    new[t] = new.get(t, 0.0) + pr * q
        dist = new
    return hit
